export declare const SCHEMA_SQL = "\nCREATE TABLE IF NOT EXISTS projects (\n  id TEXT PRIMARY KEY,\n  business_name TEXT NOT NULL,\n  industry TEXT NOT NULL,\n  website_url TEXT,\n  wordpress_url TEXT,\n  primary_locale TEXT NOT NULL DEFAULT 'en-US',\n  secondary_locales TEXT DEFAULT '[]',\n  country TEXT,\n  status TEXT DEFAULT 'draft',\n  page_count INTEGER DEFAULT 0,\n  created_at TEXT DEFAULT (datetime('now')),\n  updated_at TEXT DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS business_profiles (\n  id TEXT PRIMARY KEY,\n  project_id TEXT NOT NULL REFERENCES projects(id),\n  business_name TEXT,\n  description TEXT,\n  phone TEXT,\n  email TEXT,\n  booking_url TEXT,\n  years_in_business INTEGER,\n  trust_points TEXT DEFAULT '[]',\n  brand_colors TEXT DEFAULT '{}',\n  logo_url TEXT,\n  tone TEXT,\n  target_customer TEXT,\n  data TEXT DEFAULT '{}'\n);\n\nCREATE TABLE IF NOT EXISTS services (\n  id TEXT PRIMARY KEY,\n  project_id TEXT NOT NULL REFERENCES projects(id),\n  name TEXT NOT NULL,\n  locale TEXT NOT NULL,\n  primary_keyword TEXT,\n  secondary_keywords TEXT DEFAULT '[]',\n  slug TEXT,\n  description TEXT,\n  parent_category TEXT,\n  priority INTEGER DEFAULT 1,\n  template_type TEXT DEFAULT 'service',\n  created_at TEXT DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS locations (\n  id TEXT PRIMARY KEY,\n  project_id TEXT NOT NULL REFERENCES projects(id),\n  city TEXT NOT NULL,\n  state_province TEXT,\n  country TEXT,\n  region TEXT,\n  language_name TEXT,\n  population INTEGER,\n  priority INTEGER DEFAULT 1,\n  included INTEGER DEFAULT 1,\n  locale TEXT,\n  created_at TEXT DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS page_plans (\n  id TEXT PRIMARY KEY,\n  project_id TEXT NOT NULL REFERENCES projects(id),\n  page_type TEXT NOT NULL,\n  locale TEXT NOT NULL,\n  service_id TEXT,\n  location_id TEXT,\n  slug TEXT NOT NULL,\n  status TEXT DEFAULT 'proposed',\n  priority INTEGER DEFAULT 1,\n  created_at TEXT DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS page_briefs (\n  id TEXT PRIMARY KEY,\n  plan_id TEXT NOT NULL REFERENCES page_plans(id),\n  project_id TEXT NOT NULL REFERENCES projects(id),\n  page_type TEXT NOT NULL,\n  locale TEXT NOT NULL,\n  slug TEXT NOT NULL,\n  primary_keyword TEXT,\n  secondary_keywords TEXT DEFAULT '[]',\n  h1 TEXT,\n  meta_title TEXT,\n  meta_description TEXT,\n  section_structure TEXT DEFAULT '[]',\n  cta_angle TEXT,\n  faq_questions TEXT DEFAULT '[]',\n  internal_links TEXT DEFAULT '[]',\n  schema_types TEXT DEFAULT '[]',\n  status TEXT DEFAULT 'pending',\n  created_at TEXT DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS generated_pages (\n  id TEXT PRIMARY KEY,\n  brief_id TEXT NOT NULL REFERENCES page_briefs(id),\n  project_id TEXT NOT NULL REFERENCES projects(id),\n  locale TEXT NOT NULL,\n  slug TEXT NOT NULL,\n  page_type TEXT NOT NULL,\n  h1 TEXT,\n  meta_title TEXT,\n  meta_description TEXT,\n  content_html TEXT,\n  schema_json TEXT,\n  internal_links TEXT DEFAULT '[]',\n  status TEXT DEFAULT 'pending',\n  wp_page_id INTEGER,\n  created_at TEXT DEFAULT (datetime('now')),\n  updated_at TEXT DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS wordpress_connections (\n  id TEXT PRIMARY KEY,\n  project_id TEXT NOT NULL REFERENCES projects(id),\n  wp_url TEXT NOT NULL,\n  plugin_key TEXT NOT NULL,\n  status TEXT DEFAULT 'unverified',\n  last_checked TEXT,\n  created_at TEXT DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS deployments (\n  id TEXT PRIMARY KEY,\n  project_id TEXT NOT NULL REFERENCES projects(id),\n  status TEXT DEFAULT 'pending',\n  pages_total INTEGER DEFAULT 0,\n  pages_created INTEGER DEFAULT 0,\n  pages_failed INTEGER DEFAULT 0,\n  log TEXT DEFAULT '[]',\n  started_at TEXT,\n  completed_at TEXT,\n  created_at TEXT DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS qa_reports (\n  id TEXT PRIMARY KEY,\n  project_id TEXT NOT NULL REFERENCES projects(id),\n  deployment_id TEXT,\n  pass_count INTEGER DEFAULT 0,\n  warning_count INTEGER DEFAULT 0,\n  fail_count INTEGER DEFAULT 0,\n  total_pages INTEGER DEFAULT 0,\n  status TEXT DEFAULT 'pending',\n  created_at TEXT DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS qa_issues (\n  id TEXT PRIMARY KEY,\n  report_id TEXT NOT NULL REFERENCES qa_reports(id),\n  project_id TEXT NOT NULL REFERENCES projects(id),\n  page_slug TEXT,\n  check_name TEXT NOT NULL,\n  status TEXT NOT NULL,\n  message TEXT,\n  created_at TEXT DEFAULT (datetime('now'))\n);\n";
